from html import escape

from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi.responses import HTMLResponse
from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.auth import require_admin, require_user
from app.database import get_session
from app.models import Face, Photo, PhotoSource, Project, StorageAccount, User
from app.settings import get_app_settings
from app.ui import page

router = APIRouter(prefix="/ui", tags=["ui"])


def _search_mode_options(selected: str) -> str:
    labels = (("strict", "Strict"), ("recommended", "Recommended"), ("balanced", "Balanced"), ("broad", "Broad"))
    return "".join(f'<option value="{value}"{" selected" if value == selected else ""}>{label}</option>' for value, label in labels)


@router.get("/projects", response_class=HTMLResponse)
def projects_page(session: Session = Depends(get_session), user: User = Depends(require_user)):
    projects=session.scalars(select(Project).order_by(Project.created_at.desc())).all();cards="".join(f'<div class="card"><h2>{escape(p.name)}</h2><div class="muted">{escape(p.slug)}</div><p><a class="button" href="/ui/projects/{p.id}">Open Project</a></p></div>' for p in projects)
    create=''
    if user.role=="admin":create='<form class="row busy-form" action="/projects" method="post" data-busy-message="Creating project..."><input name="name" placeholder="Project name" required><button type="submit">Create Project</button><span class="busy-status muted" role="status"></span></form>'
    body=f'<div class="card"><h1>Projects</h1><p class="muted">Each project has an isolated catalogue and face index.</p>{create}</div>'+(cards or '<div class="card">No projects yet.</div>')+BUSY_SCRIPT
    return page("Projects",body,user=user)


@router.get("/accounts", response_class=HTMLResponse)
def accounts_page(session:Session=Depends(get_session),user:User=Depends(require_admin)):
    accounts=session.scalars(select(StorageAccount).order_by(StorageAccount.created_at.desc())).all();rows="".join(f'<tr><td>{escape(a.label)}</td><td>{escape(a.account_hint or "—")}</td><td>{escape(a.provider)}</td><td>{"Active" if a.active else "Disabled"}</td></tr>' for a in accounts)
    body=f'<div class="card"><h1>Storage Accounts</h1><p>Connect multiple Google identities. OAuth tokens stay on this computer.</p><form class="row busy-form" action="/accounts/google" method="post" data-busy-message="Opening Google connection..."><input name="label" placeholder="e.g. Event Google Account 1"><button type="submit">Connect Google Account</button><span class="busy-status muted"></span></form><p class="muted">Google connection requires credentials.json in the application folder.</p></div><div class="card"><table><thead><tr><th>Label</th><th>Account</th><th>Provider</th><th>Status</th></tr></thead><tbody>{rows or "<tr><td colspan=4>No cloud accounts connected.</td></tr>"}</tbody></table></div>{BUSY_SCRIPT}'
    return page("Storage Accounts",body,user=user)


@router.get("/projects/{project_id}",response_class=HTMLResponse)
def project_page(project_id:int,request:Request,session:Session=Depends(get_session),user:User=Depends(require_user)):
    project=session.get(Project,project_id)
    if not project:raise HTTPException(404,"Project not found")
    settings=get_app_settings(session);search_mode_options=_search_mode_options(settings.default_search_mode)
    sources=session.scalars(select(PhotoSource).where(PhotoSource.project_id==project_id).order_by(PhotoSource.id)).all();photo_count=session.scalar(select(func.count(Photo.id)).where(Photo.project_id==project_id)) or 0;pending=session.scalar(select(func.count(Photo.id)).where(Photo.project_id==project_id,Photo.indexed.is_(False))) or 0;face_count=session.scalar(select(func.count(Face.id)).where(Face.project_id==project_id)) or 0
    index_checks=''.join(f'<label><input style="min-width:auto" type="checkbox" name="source_ids" value="{s.id}" checked> {escape(s.display_name or s.source_type)}</label>' for s in sources);search_checks=index_checks
    source_rows=''.join(f'<tr><td>{escape(s.display_name or "Unnamed source")}</td><td><span class="pill">{escape(s.source_type)}</span></td><td>{escape(s.source_uri)}</td><td>{s.last_scanned_at.strftime("%Y-%m-%d %H:%M") if s.last_scanned_at else "Never"}</td><td><form class="busy-form" action="/projects/{project_id}/sources/{s.id}/scan" method="post" data-busy-message="Scanning source..."><button type="submit">Scan / Update</button><span class="busy-status muted"></span></form></td></tr>' for s in sources)
    admin_sources=''
    if user.role=="admin":
        accounts=session.scalars(select(StorageAccount).where(StorageAccount.provider=="google_drive",StorageAccount.active.is_(True))).all();opts=''.join(f'<option value="{a.id}">{escape(a.label)} — {escape(a.account_hint or "connected")}</option>' for a in accounts)
        admin_sources=f'''<div class="card"><h2>Add Google Drive Source</h2><form class="row busy-form" action="/projects/{project_id}/sources/google-drive" method="post" data-busy-message="Adding Google Drive source..."><select name="storage_account_id" required><option value="">Choose Google account</option>{opts}</select><input name="folder_url" placeholder="Google Drive folder link" required><input name="display_name" placeholder="Source name"><button type="submit">Add Drive Folder</button><span class="busy-status muted"></span></form><p class="muted"><a href="/ui/accounts">Connect another Google account</a></p></div><div class="card"><h2>Add Local / External Folder</h2><form class="row busy-form" action="/projects/{project_id}/sources/local" method="post" data-busy-message="Adding folder..."><input name="folder_path" placeholder="/Volumes/Event SSD/Photos or C:\\Photos" required><input name="display_name" placeholder="Source name"><label><input style="min-width:auto" type="checkbox" name="removable_media" value="true"> External/removable</label><button type="submit">Add Folder</button><span class="busy-status muted"></span></form></div>'''
    body=f'''<div class="row" style="justify-content:space-between"><div><h1>{escape(project.name)}</h1><div class="muted">Project-specific catalogue and face search</div></div><div class="row"><a class="button" href="/projects/{project_id}/faces/gallery">Browse Detected Faces</a><a class="button secondary" href="/ui/projects">All Projects</a></div></div><div class="grid"><div class="card"><div class="stat">{photo_count}</div><div class="muted">Catalogued photos</div></div><div class="card"><div class="stat">{pending}</div><div class="muted">Awaiting face indexing</div></div><div class="card"><div class="stat">{face_count}</div><div class="muted">Detected faces</div></div><div class="card"><div class="stat">{len(sources)}</div><div class="muted">Storage sources</div></div></div>{admin_sources}<div class="card"><h2>Storage Sources</h2><table><thead><tr><th>Source</th><th>Type</th><th>Location</th><th>Last Scan</th><th>Catalogue</th></tr></thead><tbody>{source_rows or '<tr><td colspan="5">No storage sources configured.</td></tr>'}</tbody></table></div><div class="card"><h2>1. Build / Update Face Index</h2><form id="face-index-form" class="row" action="/projects/{project_id}/faces/index" method="post">{index_checks}<button id="index-start" type="submit">Index Faces</button><button id="index-cancel" class="secondary" type="button" style="display:none">Cancel</button></form><div id="index-progress" style="display:none;margin-top:16px"><div style="height:12px;background:#e5e7eb;border-radius:999px;overflow:hidden"><div id="index-progress-bar" style="height:100%;width:0%;background:currentColor"></div></div><p><strong id="index-progress-title">Preparing...</strong></p><div id="index-progress-detail" class="muted"></div></div></div><div class="card"><h2>2. Find My Photos</h2><p class="muted">Use a selfie or upload one clear reference photo. The reference image is processed temporarily and is not stored.</p><form id="face-search-form" class="busy-form" action="/projects/{project_id}/faces/search" method="post" enctype="multipart/form-data" data-busy-message="Searching indexed faces..."><div class="row"><label class="button secondary" style="cursor:pointer">Take Selfie<input id="selfie-input" type="file" name="selfie_reference" accept="image/*" capture="user" style="display:none"></label><span class="muted">or</span><input id="reference-input" type="file" name="reference" accept="image/*"><select name="mode">{search_mode_options}</select></div><div id="reference-preview-wrap" style="display:none;margin-top:14px"><img id="reference-preview" alt="Selected reference" style="width:140px;height:140px;object-fit:cover;border-radius:12px"><span id="reference-label" class="muted" style="margin-left:12px"></span></div><div class="row" style="margin-top:12px">{search_checks}</div><p><button type="submit">Search Matching Photos</button> <span class="busy-status muted"></span></p></form></div>{BUSY_SCRIPT}{SELFIE_SCRIPT}{INDEX_SCRIPT.replace('__PROJECT_ID__',str(project_id))}'''
    return page(project.name,body,user=user)


BUSY_SCRIPT='''<script>document.querySelectorAll('form.busy-form').forEach(function(form){form.addEventListener('submit',function(event){if(form.dataset.busy==='1'){event.preventDefault();return;}form.dataset.busy='1';const button=form.querySelector('button[type="submit"]');const status=form.querySelector('.busy-status');if(button){button.disabled=true;button.textContent='Processing...';button.style.opacity='.65';}if(status)status.textContent=form.dataset.busyMessage||'Processing... Please wait.';});});</script>'''
SELFIE_SCRIPT='''<script>(function(){const form=document.getElementById('face-search-form'),selfie=document.getElementById('selfie-input'),upload=document.getElementById('reference-input'),preview=document.getElementById('reference-preview'),wrap=document.getElementById('reference-preview-wrap'),label=document.getElementById('reference-label');if(!form)return;let url=null;function selected(input,other,text){if(!input.files||!input.files[0])return;other.value='';if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(input.files[0]);preview.src=url;wrap.style.display='flex';wrap.style.alignItems='center';label.textContent=text+' — '+input.files[0].name;}selfie.addEventListener('change',function(){selected(selfie,upload,'Selfie selected');});upload.addEventListener('change',function(){selected(upload,selfie,'Photo selected');});form.addEventListener('submit',function(event){const file=(selfie.files&&selfie.files[0])||(upload.files&&upload.files[0]);if(!file){event.preventDefault();form.dataset.busy='0';alert('Take a selfie or choose a reference photo first.');return;}if(selfie.files&&selfie.files[0]){const transfer=new DataTransfer();transfer.items.add(selfie.files[0]);upload.files=transfer.files;}});})();</script>'''
INDEX_SCRIPT='''<script>(function(){const projectId=__PROJECT_ID__,form=document.getElementById('face-index-form'),start=document.getElementById('index-start'),cancel=document.getElementById('index-cancel'),box=document.getElementById('index-progress'),bar=document.getElementById('index-progress-bar'),title=document.getElementById('index-progress-title'),detail=document.getElementById('index-progress-detail');let timer=null;function render(j){const running=!!j.running;box.style.display=j.status==='idle'?'none':'block';start.disabled=running;start.textContent=running?'Indexing...':'Index Faces';cancel.style.display=running?'inline-block':'none';const pct=Number(j.percent||0);bar.style.width=Math.max(0,Math.min(100,pct))+'%';title.textContent=running?'Indexing '+(j.completed||0)+' / '+(j.total||0)+' — '+pct.toFixed(1)+'%':(j.status==='completed'?'Face indexing completed':(j.message||'Indexing status'));detail.textContent='Processed: '+(j.processed||0)+' · Faces detected: '+(j.faces||0)+' · Failed: '+(j.failed||0);if(!running&&timer){clearInterval(timer);timer=null;}}async function poll(){try{const r=await fetch('/projects/'+projectId+'/faces/index/status',{cache:'no-store'});if(r.ok)render(await r.json());}catch(e){}}function polling(){if(!timer)timer=setInterval(poll,1500);poll();}form.addEventListener('submit',async function(e){e.preventDefault();if(!form.querySelector('input[name="source_ids"]:checked')){alert('Select at least one source first.');return;}start.disabled=true;try{const r=await fetch(form.action,{method:'POST',body:new FormData(form)}),j=await r.json();if(!r.ok)throw new Error(j.detail||'Could not start indexing');render(j);polling();}catch(err){start.disabled=false;detail.textContent=err.message;}});cancel.addEventListener('click',async function(){await fetch('/projects/'+projectId+'/faces/index/cancel',{method:'POST'});polling();});poll();})();</script>'''